/// The runtime of Dart SDKs generated by tungsten (`tungsten_runtime`):
/// dart:io plus one dependency, `package:crypto`.
///
/// A generated SDK is mostly data, its SDK descriptor document (a string
/// constant), plus thin typed methods; everything with behaviour lives here,
/// so every operation behaves the same way, and the same way as the
/// TypeScript, Python, Rust, Go, Java, C# and Ruby runtimes.
///
/// [ClientCore] runs each call through one pipeline: pre-flight validation
/// of the arguments, auth (bearer with a required prefix, API keys, basic,
/// composite profiles, OAuth2 client credentials and authorization code),
/// idempotency keys, the confirmation rules of destructive operations,
/// sending with tier-aware retries, and the classification of the answer
/// (or of a lost request) into [Ok] or [Err] carrying the diagnostic
/// envelope ([Diagnostic]). On top of it: previews with confirmation tokens,
/// verification hooks, pagination, polling, macros and server-sent event
/// streams ([EventStream]). Nothing throws for an API or transport failure;
/// only invalid client options do ([ClientConfigException]).
library;

import 'dart:async';
import 'dart:collection';
import 'dart:convert';
import 'dart:io';
import 'dart:math' as math;
import 'dart:typed_data';

import 'package:crypto/crypto.dart' as crypto;

part 'src/auth.dart';
part 'src/classify.dart';
part 'src/client_core.dart';
part 'src/client_streams.dart';
part 'src/descriptors.dart';
part 'src/dispatch.dart';
part 'src/envelope.dart';
part 'src/expr.dart';
part 'src/helpers.dart';
part 'src/idempotency.dart';
part 'src/json.dart';
part 'src/macros.dart';
part 'src/oauth.dart';
part 'src/oauth_attempt.dart';
part 'src/oauth_session.dart';
part 'src/options.dart';
part 'src/pages.dart';
part 'src/schema.dart';
part 'src/serialize.dart';
part 'src/sse.dart';
part 'src/stream.dart';
part 'src/transport.dart';
part 'src/typed.dart';
part 'src/util.dart';

